insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-07-17','nieuw','Taken','Deadlines die meelopen met de planning',
   'In een actielijst-sjabloon kun je de deadline van een taak nu vastzetten op de start of het einde van de detailplanning, bijvoorbeeld "3 dagen vóór de start". Schuift de planning, dan schuiven die deadlines automatisch mee. Deadlines die je zelf hebt ingevuld blijven staan.'),
  ('2026-07-17','nieuw','Taken','Taken die zich herhalen tijdens de uitvoering',
   'Een taak in een actielijst-sjabloon kan zich herhalen zolang het werk loopt, bijvoorbeeld één keer per week. Je krijgt dan een aparte taak per keer, elk met een eigen deadline, verdeeld over de detailplanning. Duurt het werk langer of korter, dan komen er keren bij of vallen ze weg — al afgevinkte taken blijven altijd staan.');
